public sealed class FolderGuides : System.Windows.Documents.Adorner {
 readonly TreeView tree;readonly Func<string> current;
 public FolderGuides(TreeView tree,Func<string> current):base(tree){this.tree=tree;this.current=current;IsHitTestVisible=false;}
 protected override void OnRender(DrawingContext dc){var pen=new Pen(new SolidColorBrush(Color.FromArgb(40,210,215,220)),1);void Visit(ItemsControl parent){foreach(var node in parent.Items.OfType<TreeViewItem>()){if(node.Tag is string path&&(string.Equals(path.TrimEnd('\\'),current().TrimEnd('\\'),StringComparison.OrdinalIgnoreCase)||current().StartsWith(path.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase))&&node.Header is FrameworkElement header&&header.IsVisible){var pos=header.TranslatePoint(new Point(0,header.ActualHeight/2),tree);if(pos.Y>=0&&pos.Y<tree.ActualHeight)dc.DrawLine(pen,new Point(0,pos.Y),new Point(Math.Max(0,pos.X-19),pos.Y));}if(node.IsExpanded)Visit(node);}}Visit(tree);}
}
